// === Sized integer helpers (shared by the ALU and any unit working on sized operands) ===
// Wide enough for an unsigned word-by-word product, which is held as a positive value.
localparam int WIDE_SIZE = (2 * WORD_SIZE) + 2;
typedef logic signed [WIDE_SIZE-1:0] wide_t;

// The operand bit width selected by `size`; SIZE_DOUBLE is not an operand size.
function automatic int size_bits(size_e size);
    case (size)
        SIZE_BYTE: return WORD_SIZE / 4;
        SIZE_HALF: return WORD_SIZE / 2;
        default:   return WORD_SIZE;
    endcase
endfunction

function automatic logic size_is_operand(size_e size);
    return size == SIZE_BYTE || size == SIZE_HALF || size == SIZE_WORD;
endfunction

// Largest and smallest value that fits in `bits` bits.
function automatic wide_t range_max(int bits, logic is_signed);
    return is_signed ? (wide_t'(1) <<< (bits - 1)) - 1 : (wide_t'(1) <<< bits) - 1;
endfunction

function automatic wide_t range_min(int bits, logic is_signed);
    return is_signed ? -(wide_t'(1) <<< (bits - 1)) : wide_t'(0);
endfunction

